/**
 * A route param as the app compares it: DECODED.
 *
 * Next hands `[slug]` and `[...segments]` to a page percent-ENCODED, and
 * every slug is stored decoded (`src/fields/slug.ts`'s rule). Until
 * 2026-09-23 the tools page compared the two raw, so `roi計算ツール` arrived
 * as `roi%E8%A8%88…`, matched nothing, and every tool page in the eight
 * non-Latin locales — zh, tc, ar, uk, th, he, ko, ja, 328 pages — was a 404
 * under an index that linked to it.
 *
 * A malformed escape is not a slug: it falls through as-is and matches
 * nothing, so the page 404s it like any unknown slug. A bare
 * `decodeURIComponent` throws URIError on one instead (`/it/x%E0%A4`), which
 * is what ELECTE-2697 was: the main site's `[...segments]`, help, the
 * quarterly pages and the markdown twin each decoded on their own and
 * answered 500 to a mangled link. `decodeSlug.test.ts` fails a route that
 * goes back to the bare call.
 */
export function decodeSlug(raw: string): string {
  try {
    return decodeURIComponent(raw)
  } catch {
    return raw
  }
}
